_CSRF_SESSION_KEY = "_csrf_token"


def _origin_tuple(value):
    try:
        parsed = urlparse(value)
        if parsed.scheme not in {"http", "https"} or not parsed.hostname:
            return None
        port = parsed.port or (443 if parsed.scheme == "https" else 80)
    except ValueError:
        return None
    return parsed.scheme, parsed.hostname.lower(), port



def get_csrf_token():
    """Bu oturuma bağlı CSRF synchronizer token'ı döndür (yoksa üret ve sakla).

    Token, imzalı oturum çerezinde tutulur (sunucu-taraflı kanıt). Şablonlara
    <meta name="csrf-token"> ile sızdırılır; frontend (static/csrf.js) durum-
    değiştiren her fetch'e X-CSRFToken başlığı olarak ekler. _csrf_protect bu
    başlığı oturumdaki değerle karşılaştırır."""
    token = session.get(_CSRF_SESSION_KEY)
    if not token:
        token = secrets.token_urlsafe(32)
        session[_CSRF_SESSION_KEY] = token
    return token


def inject_csrf_token():
    return {"csrf_token": get_csrf_token()}


def inject_i18n():
    """Şablonlara çeviri yardımcısını sun: `t` (callable), `locale` (aktif dil)
    ve `i18n_catalog` (window.I18N'e enjekte edilen, aktif dilin tam sözlüğü —
    HAM dict; şablon `|tojson` ile güvenli gömer).
    g.locale resolve_locale (before_request) tarafından set edilir."""
    from app.i18n import t, current_locale, catalog
    loc = current_locale()
    return {
        "t": t,
        "locale": loc,
        # HAM dict döndür; şablonda `|tojson` kullanılır (json.dumps+|safe DEĞİL).
        # `|tojson` `<`, `>`, `&`, U+2028/2029'u kaçırır → inline <script> içine
        # güvenli gömülür; ham json.dumps `</script>` dizisini kaçırmıyordu (S2).
        "i18n_catalog": catalog(loc, exclude_prefixes=("weekly_program.",)),
    }


