def _rollover_throttle_passed(now):
    """5-dk rollover-kontrol throttle'ı — bu istek kontrolü çalıştırmalı mı?

    Redis varsa FLEET-GENELİ: tüm gunicorn worker'ları tek bir Redis anahtarını
    (NX+EX 300s) paylaşır → 5 dk'da yalnızca BİR worker rollover kontrolünü çalıştırır.
    Redis yoksa/erişilemezse süreç-içi `_last_rollover_check`'e düşer (eski tek-worker
    davranışı). Throttle yalnızca bir SIKLIK optimizasyonudur — rollover'ın kendisi
    WeeklyResetLog UNIQUE kısıtıyla zaten idempotent; throttle birkaç worker'da birden
    geçse bile çift ödül OLMAZ. Bu sayede worker sayısı güvenle >1'e çıkarılabilir (#17)."""
    from app.extensions import redis_client
    if redis_client is not None:
        try:
            # NX: anahtar yoksa kur (True) → bu worker kontrol etsin. Varsa (son 5 dk'da
            # biri kontrol etmiş) None → atla. EX 300: pencere 5 dk sonra kendini siler.
            return bool(redis_client.set("fitx:rollover_check", "1", nx=True, ex=300))
        except Exception:
            pass  # Redis erişilemiyor → süreç-içi yedeğe düş

    last = _last_rollover_check[0]
    if last is not None and (now - last).total_seconds() < 300:
        return False
    _last_rollover_check[0] = now
    return True


# M1: süresi geçmiş Cognito oturum satırlarının süpürülmesi. purge_expired'ın
# TEK çağıranı weekly-reset CLI'ıydı ve o da yalnızca bir EC2 host cron'unun VAR
# OLDUĞUNU VARSAYIYORDU — repo'da, compose'da veya deploy'da bu cron'u kuran
# hiçbir şey yok. Cron eksikse (ya da bir host yeniden kurulumunda kaybolduysa)
# tablo sınırsız büyür ve 30 günü geçmiş, artık yenilenemeyen şifreli refresh
# token'ları saklamaya devam eder. Zamanlamayı repo'ya al: rollover ile aynı
# NX-kilit desenini kullanan, kendi kendini onaran GÜNLÜK bir süpürme.
_last_purge_check = [None]
_PURGE_INTERVAL_SECONDS = 86400


def _purge_throttle_passed(now):
    """Günde bir kez, fleet genelinde tek worker süpürsün."""
    from app.extensions import redis_client
    if redis_client is not None:
        try:
            return bool(redis_client.set("fitx:session_purge", "1", nx=True,
                                         ex=_PURGE_INTERVAL_SECONDS))
        except Exception:
            pass  # Redis erişilemiyor → süreç-içi yedeğe düş

    last = _last_purge_check[0]
    if last is not None and (now - last).total_seconds() < _PURGE_INTERVAL_SECONDS:
        return False
    _last_purge_check[0] = now
    return True


def maybe_weekly_rollover():
    now = datetime.utcnow()
    if not _rollover_throttle_passed(now):
        return
    try:
        run_weekly_rollover(app_now())
    except Exception:
        db.session.rollback()
        # Sessizce yutma: rollover hatası liderlik/ödül tutarlılığını bozabilir,
        # olay tespiti için logla (S6/3.6).
        current_app.logger.warning("[ROLLOVER] Haftalık rollover başarısız", exc_info=True)

    # Bakım penceresini paylaş ama AYRI throttle kullan: rollover haftalık,
    # süpürme günlüktür ve rollover hata verse bile süpürme çalışmalıdır.
    if not _purge_throttle_passed(now):
        return
    try:
        from app.services import session_store
        session_store.purge_expired()
    except Exception:
        db.session.rollback()
        current_app.logger.warning("[SESSION] Oturum süpürme başarısız", exc_info=True)
    # Aynı günlük pencerede eski bildirimler de süpürülür (Sprint 5 PR1) —
    # ayrı throttle anahtarı yok; oturum süpürmesi hata verse bile denenir.
    try:
        from app.services import notifications
        notifications.purge_old(now)
    except Exception:
        db.session.rollback()
        current_app.logger.warning("[NOTIF] Bildirim süpürme başarısız", exc_info=True)


def update_streak():
    if not current_user.is_authenticated:
        return
    today = app_today()
    # Hızlı yol: bugün zaten işlendiyse kilit alma (isteklerin çoğu buraya düşer).
    if current_user.last_login == today:
        return
    # Günün İLK isteği. 8 thread'lik gunicorn'da aynı kullanıcının paralel
    # istekleri (sayfa açılışında birden çok fetch) ikisi de last_login != today
    # görüp streak'i iki kez artırabilir / milestone XP'yi iki kez verebilirdi.
    # Kullanıcı satırını kilitleyip tekrar kontrol ederek tek artışı garanti et.
    # DİKKAT (C1): kilitli yeniden-kontrol KOLON sorgusuyla yapılmalı. Entity
    # sorgusu identity map'ten istek başında yüklenen current_user'ı döndürür ve
    # kilit altında SELECT'lenen taze last_login'i ATAR — diğer thread commit'lemiş
    # olsa bile burada bayat "dün" görünür ve streak/milestone XP çift işlenirdi.
    row = (db.session.query(User.last_login, User.streak_count)
           .filter_by(id=current_user.id).with_for_update().first())
    if row is None or row[0] == today:
        # Başka bir istek bu kullanıcı için zaten güncelledi.
        db.session.commit()  # FOR UPDATE kilidini serbest bırak
        return
    prev_last_login = row[0]
    user = current_user._get_current_object()  # session'daki örnek; kilit bizde
    if prev_last_login == today - timedelta(days=1):
        user.streak_count = (row[1] or 0) + 1
    else:
        user.streak_count = 1
    # Bu istekten ÖNCEKI last_login'i sakla: get_nudges seri-riski dürtüsünü
    # "günün ilk isteğinde henüz aktif değildi" mantığıyla doğru tetiklesin
    # (aksi halde aşağıdaki güncelleme yüzünden asla tetiklenmez).
    g.prev_last_login = prev_last_login
    user.last_login = today
    # Challenge huni: bu kilitli dal Istanbul-günü başına TAM BİR KEZ çalışır →
    # 'active_day' metriği günde bir kez artar (aynı transaction, commit aşağıda).
    from app.services.challenges import record_event
    record_event(user.id, "active_day")
    streak = user.streak_count
    if streak in (7, 14, 30, 60, 100):
        log_activity(user.id, "streak_milestone",
                     f"{streak} günlük seri yakalandı!")
        award_xp(user.id, streak * 2)
    # streak tiebreak'i değişti → commit sonrası Redis sync (after_commit).
    # Milestone yoksa award_xp dirty işaretlemez; burada elle işaretliyoruz.
    _mark_lb_dirty(user.id)
    # Savunma derinliği (triage #2): çıplak commit'i koru. record_event savepoint
    # ile poison'ı önler ama başka bir nadir DB arızası (kilit çakışması) burada
    # PendingRollbackError verirse, çıplak commit istek için 500 üretirdi. Her
    # diğer yazı yolu zaten böyle korunur. Rollback FOR UPDATE kilidini de bırakır;
    # streak güncellemesi bu istekte kaybolur (bir sonraki istekte tekrar denenir).
    try:
        db.session.commit()
    except Exception:
        db.session.rollback()
        current_app.logger.warning("[STREAK] güncelleme commit başarısız (geri alındı)",
                                   exc_info=True)


def inject_rank():
    base = {"_v": _BOOT_TS}
    if current_user.is_authenticated:
        xp = current_user.rank_points or 0
        level = get_level(xp)
        title = level_title(level)  # GÖRÜNEN ünvan → g.locale'a göre
        xp_in_level = xp % 500
        return {**base,
            "rank_points": xp, "rank_title": title,
            "user_xp": xp, "user_level": level, "user_title": title,
            "xp_in_level": xp_in_level, "xp_for_next": 500,
        }
    anon_title = level_title(1)
    return {**base,
        "rank_points": 0, "rank_title": anon_title,
        "user_xp": 0, "user_level": 1, "user_title": anon_title,
        "xp_in_level": 0, "xp_for_next": 500,
    }


